<?php
require __DIR__.'/includes/session.php'; require __DIR__.'/includes/account-layout.php'; require __DIR__.'/includes/achievement-tiers.php'; require __DIR__.'/includes/achievement-view.php';
require_account();
$rows=[]; $titles=[]; $error=''; try { $db=spellstorm_database(); $rows=$db->query('SELECT p.user_id,p.username,max(r.score) AS score FROM public.player_profiles p JOIN public.game_runs r ON r.user_id=p.user_id GROUP BY p.user_id,p.username ORDER BY score DESC,p.username LIMIT 100')->fetchAll(PDO::FETCH_ASSOC); $titles=player_title_map($db); } catch(Throwable $e) { $error='Leaderboard temporarily unavailable.'; }
account_header('Global leaderboard',true); ?>
<p>Best score per player. Achievement titles appear beside player names.</p><?php if($error): ?><p class="error"><?=escape($error)?></p><?php elseif(!$rows): ?><p>No runs recorded yet.</p><?php else: ?><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Rank</th><th>Player</th><th>Best score</th></tr></thead><tbody><?php $rank=0;$previous=null; foreach($rows as $i=>$row): if($previous!==$row['score']) $rank=$i+1; $previous=$row['score']; ?><tr><td><?=$rank?></td><td><img src="avatar.php?id=<?=escape($row['user_id'])?>" width="32" height="32" class="rounded-circle object-fit-cover me-2" alt="" loading="lazy"><?=escape($row['username'])?> <?php achievement_badge($titles[$row['user_id']]??null); ?></td><td><?=number_format((int)$row['score'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; account_footer(); ?>
